// Writes engine/types/<name>.gen.ts for every schemas/<name>.v<N>.json, plus the engine/types.ts barrel.
// Usage: node tools/gen-types.ts [--check]
// --check writes nothing and exits 1 when any generated file is missing, stale or orphaned.

import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildRegistry, checkSchema, formatError, type Schema, type SchemaObject } from "../engine/schema/validate.ts";

export type SchemaFile = { file: string; schema: Schema };

/** Output path relative to the repo root, mapped to its contents. */
export type Generated = Map<string, string>;

type Named = { module: string; type: string };

const pascal = (s: string): string => s.split(/[^A-Za-z0-9]+/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join("");
const moduleName = (file: string): string => file.replace(/\.json$/, "").replace(/\.v\d+$/, "");
const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const key = (k: string): string => (/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k));

/** Pure: schemas in, generated files out. Throws with every problem listed when the schemas cannot be typed. */
export function generate(files: SchemaFile[]): Generated {
  const sorted = [...files].sort((a, b) => (a.file < b.file ? -1 : 1));
  const problems: string[] = [];
  const { registry, errors } = buildRegistry(sorted.map((f) => f.schema));
  problems.push(...errors.map(formatError));

  const names = new Map<unknown, Named>();
  const ids = new Map<string, Named>();
  const exported = new Map<string, string>();
  const claim = (file: string, named: Named, node: unknown) => {
    const owner = exported.get(named.type);
    if (owner !== undefined) problems.push(`${file}: type ${named.type} is also exported by ${owner}`);
    exported.set(named.type, file);
    names.set(node, named);
    if (isObject(node) && typeof node.$id === "string" && node.$id.startsWith("numberone:")) ids.set(node.$id, named);
  };
  for (const { file, schema } of sorted) {
    const module = moduleName(file);
    problems.push(...checkSchema(schema, registry).map((e) => `${file}: ${formatError(e)}`));
    claim(file, { module, type: pascal(module) }, schema);
    const defs = isObject(schema) && isObject(schema.$defs) ? schema.$defs : {};
    for (const [name, def] of Object.entries(defs)) claim(file, { module, type: pascal(name) }, def);
  }
  if (problems.length > 0) throw new Error(problems.join("\n"));

  const out: Generated = new Map();
  for (const { file, schema } of sorted) {
    const module = moduleName(file);
    const imports = new Map<string, Set<string>>();
    const refType = (ref: string, root: Schema): string => {
      const named = ref.startsWith("#") ? names.get(resolveLocal(root, ref.slice(1))) : ids.get(ref);
      if (named === undefined) throw new Error(`${file}: $ref ${ref} must name a schema root or a $defs entry`);
      if (named.module !== module) {
        if (!imports.has(named.module)) imports.set(named.module, new Set());
        imports.get(named.module)!.add(named.type);
      }
      return named.type;
    };
    const decls = [`export type ${pascal(module)} = ${typeOf(schema, schema, refType, 0)};`];
    const defs = isObject(schema) && isObject(schema.$defs) ? schema.$defs : {};
    for (const [name, def] of Object.entries(defs)) decls.push(`export type ${pascal(name)} = ${typeOf(def as Schema, schema, refType, 0)};`);
    const importLines = [...imports].sort(([a], [b]) => (a < b ? -1 : 1))
      .map(([m, types]) => `import type { ${[...types].sort().join(", ")} } from "./${m}.gen.ts";`);
    const header = `// generated from schemas/${file} by tools/gen-types.ts, do not edit`;
    out.set(`engine/types/${module}.gen.ts`, [header, ...importLines, "", ...decls, ""].join("\n"));
  }
  const barrel = [...out.keys()].map((p) => `export type * from "./${p.slice("engine/".length)}";`);
  out.set("engine/types.ts", ["// generated by tools/gen-types.ts, do not edit", ...barrel, ""].join("\n"));
  return out;
}

function resolveLocal(root: Schema, pointer: string): unknown {
  let node: unknown = root;
  for (const raw of pointer.split("/").slice(1)) {
    const k = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    node = isObject(node) ? node[k] : undefined;
  }
  return node;
}

function typeOf(schema: Schema, root: Schema, refType: (ref: string, root: Schema) => string, indent: number): string {
  if (schema === true) return "unknown";
  if (schema === false) return "never";
  const s = schema as SchemaObject;
  if (typeof s.$id === "string" && s !== root) root = s;
  const parts: string[] = [];
  if (s.$ref !== undefined) parts.push(refType(s.$ref, root));
  if (s.const !== undefined) parts.push(JSON.stringify(s.const));
  else if (s.enum !== undefined) parts.push(s.enum.map((e) => JSON.stringify(e)).join(" | "));
  else if (s.oneOf !== undefined) parts.push(s.oneOf.map((b) => wrap(typeOf(b, root, refType, indent))).join(" | "));
  else if (s.type !== undefined) {
    const types = Array.isArray(s.type) ? s.type : [s.type];
    parts.push(types.map((t) => (t === "object" ? objectType(s, root, refType, indent) : t === "array" ? arrayType(s, root, refType, indent) : t === "integer" ? "number" : t)).join(" | "));
  } else if (s.properties !== undefined) parts.push(objectType(s, root, refType, indent));
  if (parts.length === 0) return "unknown";
  return parts.length === 1 ? parts[0] : parts.map(wrap).join(" & ");
}

/** Properties with a `default` are required: types describe documents after validate() fills defaults. */
function objectType(s: SchemaObject, root: Schema, refType: (ref: string, root: Schema) => string, indent: number): string {
  const pad = "  ".repeat(indent + 1);
  const required = new Set(s.required ?? []);
  const props = Object.entries(s.properties ?? {});
  const lines = props.map(([k, sub]) => {
    const optional = !required.has(k) && !(isObject(sub) && "default" in sub);
    return `${pad}${key(k)}${optional ? "?" : ""}: ${typeOf(sub, root, refType, indent + 1)};`;
  });
  if (s.additionalProperties !== false) {
    const extra = s.additionalProperties === undefined || s.additionalProperties === true ? "unknown" : typeOf(s.additionalProperties, root, refType, indent + 1);
    const values = extra === "unknown" ? extra : [extra, ...props.map(([, sub]) => typeOf(sub, root, refType, indent + 1))].map(wrap).join(" | ");
    lines.push(`${pad}[key: string]: ${values};`);
  }
  return lines.length === 0 ? "Record<string, never>" : `{\n${lines.join("\n")}\n${"  ".repeat(indent)}}`;
}

function arrayType(s: SchemaObject, root: Schema, refType: (ref: string, root: Schema) => string, indent: number): string {
  const item = s.items === undefined ? "unknown" : typeOf(s.items, root, refType, indent);
  return /^[\w.]+$/.test(item) ? `${item}[]` : `Array<${item}>`;
}

const wrap = (t: string): string => (/^[\w."-]+$/.test(t) || t.startsWith("{") || t.startsWith("Array<") ? t : `(${t})`);

function readSchemas(repo: string): SchemaFile[] {
  const dir = join(repo, "schemas");
  return readdirSync(dir).filter((f) => f.endsWith(".json")).sort()
    .map((file) => ({ file, schema: JSON.parse(readFileSync(join(dir, file), "utf8")) as Schema }));
}

function main(argv: string[]): number {
  const repo = join(fileURLToPath(import.meta.url), "..", "..");
  const check = argv.includes("--check");
  let generated: Generated;
  try {
    generated = generate(readSchemas(repo));
  } catch (e) {
    console.error((e as Error).message);
    return 1;
  }
  const typesDir = join(repo, "engine", "types");
  const orphans = existsSync(typesDir)
    ? readdirSync(typesDir).filter((f) => f.endsWith(".gen.ts")).map((f) => `engine/types/${f}`).filter((p) => !generated.has(p))
    : [];
  const stale = [...generated].filter(([p, text]) => !existsSync(join(repo, p)) || readFileSync(join(repo, p), "utf8") !== text).map(([p]) => p);
  if (check) {
    for (const p of [...stale, ...orphans]) console.error(`stale: ${p}`);
    if (stale.length + orphans.length > 0) console.error("run: node tools/gen-types.ts");
    return stale.length + orphans.length > 0 ? 1 : 0;
  }
  mkdirSync(typesDir, { recursive: true });
  for (const p of stale) writeFileSync(join(repo, p), generated.get(p)!);
  for (const p of orphans) rmSync(join(repo, p));
  console.log(`gen-types: ${generated.size} files, ${stale.length} written, ${orphans.length} removed`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
